SELECT sale_cohort, product_id, row_count FROM (SELECT CASE WHEN YEAR(sale_date) < 2024 THEN 'before_2024' WHEN YEAR(sale_date) = 2024 THEN '2024' ELSE 'after_2024' END AS sale_cohort, product_id, COUNT(*) AS row_count FROM store_sales WHERE units BETWEEN 23 AND 32 GROUP BY CASE WHEN YEAR(sale_date) < 2024 THEN 'before_2024' WHEN YEAR(sale_date) = 2024 THEN '2024' ELSE 'after_2024' END, product_id) AS agg WHERE row_count < 10 ORDER BY sale_cohort, product_id LIMIT 3
